function addToCart(button, productName, price, imageUrl) {
  // Find or create cart item
  const existingItem = cartItems.find(item => item.name === productName);
  if (existingItem) {
    existingItem.quantity += 1;
  } else {
    cartItems.push({
      id: Date.now(),
      name: productName,
      price: price,
      image: imageUrl,
      quantity: 1
    });
  }
  cartCount++;

  // Save to localStorage
  saveCartToStorage();

  // Create fly-to-cart animation
  createFlyToCartAnimation(button, imageUrl);

  // Show notification
  showCartNotification(productName, imageUrl);

  // Update cart count with animation
  setTimeout(() => {
    updateCartDisplay();
    document.getElementById('cartCount').classList.add('animate');
    setTimeout(() => {
      document.getElementById('cartCount').classList.remove('animate');
    }, 600);
  }, 500);

  // Trigger the cart icon animation
  setTimeout(() => {
    triggerCartAnimation();
  }, 700);
}

function proceedToCheckout() {
  if (cartItems.length === 0) {
    alert('Your cart is empty!');
    return;
  }
  // Calculate total
  const total = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
  // Save total to localStorage
  localStorage.setItem('quickCartTotal', total.toFixed(2));
  // Redirect to payment page
  window.location.href = 'index14.html';
}

