function updateTotal() {
  let total = 0;
  document.querySelectorAll('.cart-item').forEach(item => {
    const price = parseInt(item.getAttribute('data-price'));
    const qty = parseInt(item.querySelector('.cart-qty-input').value);
    total += price * qty;
  });
  document.getElementById('cartTotal').textContent = '₹' + total.toLocaleString();
}

function updateSubtotal(input) {
  const item = input.closest('.cart-item');
  const price = parseInt(item.getAttribute('data-price'));
  const qty = parseInt(input.value);
  const subtotal = price * qty;
  item.querySelector('.cart-subtotal').textContent = 'Subtotal: ₹' + subtotal.toLocaleString();
  updateTotal();
}

function triggerCartAnimation() {
  const cartIcon = document.getElementById('cartIcon');
  const cartCountElement = document.getElementById('cartCount');

  // Reset animations
  cartIcon.classList.remove('cart-icon-animate');
  cartCountElement.classList.remove('cart-count-pop');

  // Trigger reflow
  void cartIcon.offsetWidth;
  void cartCountElement.offsetWidth;

  // Add animations
  cartIcon.classList.add('cart-icon-animate');
  cartCountElement.classList.add('cart-count-pop');

  // Remove classes after animation
  setTimeout(() => {
    cartIcon.classList.remove('cart-icon-animate');
    cartCountElement.classList.remove('cart-count-pop');
  }, 600);
}

